/// Number of plots, in rawfile order (one per analysis card, except
/// `.noise` with 1-2 and `.disto` with 2-3; 0 on failure).
///
/// # Safety
///
/// `result` is NULL or a live result from `dune_simulate*`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_result_plot_count(result: *const DuneResult) -> usize {
    // SAFETY: caller's contract.
    unsafe { result_ref(result) }.map_or(0, |r| r.plots.len())
}

/// The plot's `Plotname:` (e.g. `"Transient Analysis"`), or NULL when
