#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_name(result: *const DuneResult, plot: usize) -> *const c_char {
    // SAFETY: caller's contract.
    unsafe { plot_ref(result, plot) }.map_or(ptr::null(), |p| p.name.as_ptr())
}

