/// Number of points (rows) of the plot - every column has this
/// length; 0 when out of range.
///
/// # Safety
///
/// `result` is NULL or a live result from `dune_simulate*`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_npoints(result: *const DuneResult, plot: usize) -> usize {
    // SAFETY: caller's contract.
    unsafe { plot_ref(result, plot) }.map_or(0, |p| p.solution.num_points())
}

/// True when the plot's data is complex (`.ac`, `.sp`, `.disto`,
/// `.pz`...): read it with `dune_plot_column_complex`. False when out
/// of range.
///
/// # Safety
///
/// `result` is NULL or a live result from `dune_simulate*`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_is_complex(result: *const DuneResult, plot: usize) -> bool {
    // SAFETY: caller's contract.
    unsafe { plot_ref(result, plot) }.is_some_and(|p| p.is_complex())
}

/// Index of the plot's scale (abscissa: `time`, `frequency`,
/// `v(v-sweep)`...) among its variables; -1 when the plot has none
/// (operating point, `.tf`, `.sens` DC...) or `plot` is out of range.
///
/// # Safety
///
/// `result` is NULL or a live result from `dune_simulate*`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_scale_index(result: *const DuneResult, plot: usize) -> isize {
    // SAFETY: caller's contract.
    unsafe { plot_ref(result, plot) }
        .and_then(|p| p.solution.scale)
        .and_then(|s| isize::try_from(s).ok())
        .unwrap_or(-1)
}

/// Borrow the **real** column `var` of the plot, without a copy:
/// `*out_ptr` receives a pointer to `*out_len` doubles (the plot's
/// `npoints`), valid until `dune_result_free(result)`.
///
/// Returns false - and stores NULL/0 into whichever out pointer is
/// not NULL - when `result` is NULL, an index is out of range, the
/// plot is complex, or an out pointer is NULL. With `*out_len == 0`
/// the pointer is non-NULL but must not be dereferenced.
///
/// # Safety
///
/// `result` is NULL or a live result from `dune_simulate*`;
/// `out_ptr`/`out_len` are NULL or valid for one write. The data is
/// read-only and must not be read past `*out_len` doubles.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_column_real(
    result: *const DuneResult,
    plot: usize,
    var: usize,
    out_ptr: *mut *const f64,
    out_len: *mut usize,
) -> bool {
    // SAFETY: caller's contract.
    let column = unsafe { plot_ref(result, plot) }
        .and_then(|p| p.column_real(var))
        .map(|c| (c.as_ptr(), c.len()));
    // SAFETY: out pointers are NULL or valid for one write.
    unsafe { write_column(column, out_ptr, out_len) }
}

/// Borrow the **complex** column `var` of the plot, without a copy,
/// as interleaved pairs: `*out_ptr` points to `*out_len` doubles laid
/// out `re0, im0, re1, im1, ...` - so `*out_len` is **twice** the
/// plot's `npoints`, and point k is `(p[2k], p[2k+1])` (the layout of
/// a C99 `double _Complex` array). Valid until
/// `dune_result_free(result)`.
///
/// Returns false - and stores NULL/0 into whichever out pointer is
/// not NULL - when `result` is NULL, an index is out of range, the
/// plot is real, or an out pointer is NULL.
///
/// # Safety
///
/// As [`dune_plot_column_real`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dune_plot_column_complex(
    result: *const DuneResult,
    plot: usize,
    var: usize,
    out_ptr: *mut *const f64,
    out_len: *mut usize,
) -> bool {
    // SAFETY: caller's contract.
    let column = unsafe { plot_ref(result, plot) }.and_then(|p| p.column_complex(var));
    // SAFETY: out pointers are NULL or valid for one write.
    unsafe { write_column(column, out_ptr, out_len) }
}

/// Store a column into the out pointers (NULL/0 when `column` is
/// `None` or either pointer is NULL); true when a column was stored.
///
/// # Safety
///
/// `out_ptr`/`out_len` are NULL or valid for one write.
unsafe fn write_column(
    column: Option<(*const f64, usize)>,
    out_ptr: *mut *const f64,
    out_len: *mut usize,
) -> bool {
    let column = column.filter(|_| !out_ptr.is_null() && !out_len.is_null());
    let (p, n) = column.unwrap_or((ptr::null(), 0));
    // SAFETY: each pointer is written only when non-NULL; the caller
    // guarantees non-NULL pointers are valid for a write.
    unsafe {
        if !out_ptr.is_null() {
            out_ptr.write(p);
        }
        if !out_len.is_null() {
            out_len.write(n);
        }
    }
    column.is_some()
}

#[cfg(test)]
mod tests;
